INSERT INTO `chatbot_categories` VALUES (1,'room-information','Room Information','fa-bed','Sure! I can help you with information about our rooms, rates, amenities, and availability. What would you like to know?','View Rooms','#rooms','room, rooms, room info, room information, kwarto',1,1,'2026-11-17 19:13:41','2026-11-17 19:13:41'),(2,'reservation','Reservation','fa-calendar-check','I can guide you through the reservation process and help you understand the booking requirements.','Go to Reservations','/tenants/reservations','reservation, reserve, booking, book',2,1,'2026-11-17 19:13:41','2026-11-17 19:13:41'),(3,'payment-billing','Payment and Billing','fa-wallet','I can help you with payment options, down payments, and billing concerns.','Go to Reservations','/tenants/reservations','payment, billing, pay, bayad, invoice',3,1,'2026-11-17 19:13:41','2026-11-17 19:13:41'),(4,'house-rules','House Rules and Policies','fa-scroll','Here are some important rules and policies to help maintain a safe and comfortable environment for all tenants.','View Full Policies','chat:policies','rules, policy, policies, house rules, regulations, bawal',4,1,'2026-11-17 19:13:41','2026-11-17 19:13:41'),(5,'services-requests','Services and Requests','fa-screwdriver-wrench','I can help you understand the services available to current tenants, including maintenance concerns, room changes, and stay extensions.','Go to Services','/tenants/services/maintenance','services, service, requests, request, tenant services',5,1,'2026-11-17 19:13:41','2026-11-17 19:13:41'),(6,'contact-location','Contact and Location','fa-location-dot','Here is how you can reach us or find our place.','Contact Us','#contact','contact, location, address, where, reach',6,1,'2026-11-17 19:13:41','2026-11-17 19:13:41');
DROP TABLE IF EXISTS `chatbot_faqs`;
