  `answer` text NOT NULL,
  `keywords` text NOT NULL,
  `sort_order` int(10) unsigned NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `hits` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `chatbot_faqs_chatbot_category_id_foreign` (`chatbot_category_id`),
  CONSTRAINT `chatbot_faqs_chatbot_category_id_foreign` FOREIGN KEY (`chatbot_category_id`) REFERENCES `chatbot_categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

INSERT INTO `chatbot_faqs` VALUES (1,1,'What room types are available?','You can browse the available room types in the Rooms section of our website. Each room includes its details, capacity, and amenities.\n\nWe currently offer:\n{{room_types}}','room type, types of room, kind of room, room types, solo, barkada, bedspace, options, offer',1,1,1,'2026-11-17 19:13:41','2026-11-17 19:21:33'),(2,1,'How much is the room rate?','Room rates depend on the selected room type. You can view the corresponding rates in the Rooms section.\n\nCurrent daily rates:\n{{room_rates}}','rate, how much, price, cost, magkano, per day, daily, monthly, rent, cheapest',2,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(3,1,'What are the room amenities?','Room amenities and facilities are provided in each room\'s details. Please visit the Rooms section to learn more.\n\nAll tenants enjoy: High-Speed Wi-Fi, air-conditioned & fan room options, Netflix access, 24/7 CCTV security, a shared kitchen, and a laundry area.','amenities, inclusions, included, facilities, wifi, aircon, netflix, kitchen, laundry, cctv',3,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(4,1,'How can I check room availability?','Visit the Rooms section to see the current status of each room: Available, Reserved, or Occupied.\n\nRight now:\n{{room_availability}}','available, availability, vacant, vacancy, still available, bakante, occupied, full',4,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(5,1,'What is the difference between Solo, Barkada, and Bedspace?','• Solo Room — a private room just for you.\n• Barkada Room — the whole room is booked for your group of friends.\n• Bedspace — you rent a single bed (upper or lower deck) in a shared room.\n\nCapacity and rates for each are shown in the Rooms section.','difference, solo, barkada, bedspace, shared, private, group, compare',5,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(6,1,'Can I see the room before booking?','Yes! Rooms with a \"Virtual Tour\" button in the Rooms section have a 360° tour so you can look around before you reserve. You may also contact us to arrange a visit during office hours (Mon–Sun, 8:00 AM – 8:00 PM).','see the room, virtual tour, 360, tour, visit the room, look, pictures, photos, ocular, viewing',6,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(7,2,'How can I reserve a room?','Create an account, browse available rooms, select your preferred room, and submit a reservation request.','how to reserve, how to book, reserve, book a room, booking process, steps, magpareserve',1,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(8,2,'What are the reservation requirements?','You must provide the required personal information and reservation details. Additional requirements may be requested during the process. Upon move-in, you may be asked to present a valid ID and your reservation confirmation.','requirements, documents, needed, valid id, what do i need, prepare',2,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(9,2,'Is my reservation automatically approved?','No. All reservation requests are subject to administrator review and approval. Your request stays under \"Pending Verification\" until the admin reviews it, and you will be notified once it is approved or rejected.','automatically approved, approve, approval, confirmed, pending, instant, auto',3,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(10,2,'How can I check my reservation status?','Log in to your account and visit the Reservations section to view your current reservation status.','reservation status, check status, track, my reservation, update',4,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(11,2,'Can I change my reserved room?','Room changes are subject to room availability and administrator approval. Please submit a request through the system.','change room, change reserved room, switch room, transfer, different room',5,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(12,2,'Do I need an account to book?','Yes. Click \"Sign Up\" at the top of the page to create a free account, complete your profile and ID verification, then you can reserve a room.','account, sign up, signup, register, create account, login, need account',6,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(13,2,'What is the minimum stay?','The minimum stay is 24 hours (1 full day). You choose your check-in and check-out date and time when you submit your reservation.','minimum stay, minimum, shortest, how long, one day, overnight stay, short stay',7,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(14,2,'What time is check-in and check-out?','You pick your preferred check-in and check-out date and time in the reservation form. Just make sure the stay is at least 24 hours and any remaining balance is settled before check-in.','check in, check-in, checkin, check out, check-out, checkout, arrival, time',8,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(15,2,'Can I cancel my reservation?','Reservation cancellations and changes to reservation details are subject to room availability, applicable policies, and administrator approval. Please contact the administrator for assistance with your specific booking.','cancel, cancellation, refund, refundable, back out',9,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(16,2,'What happens if I do not show up?','Reservations may expire if the requirements are not completed within the specified period or if the tenant fails to arrive on the scheduled move-in date, subject to the applicable reservation conditions.','no show, did not arrive, expire, expired, late arrival, miss',10,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(17,3,'What payment methods do you accept?','Reservation payments are made through GCash. Enter your GCash reference details and upload your proof of payment in the reservation form so the admin can verify it.','payment method, mode of payment, gcash, how to pay, pay, bank, cash, accept',1,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(18,3,'Do I need to pay a down payment?','You can choose either a 50% down payment or full payment when you reserve. If you choose the 50% down payment, the remaining 50% balance must be settled before your scheduled check-in date and time.','down payment, downpayment, dp, deposit, partial, 50%, half, full payment',2,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(19,3,'When should I pay the remaining balance?','The remaining balance must be settled before your scheduled check-in date and time. You will receive reminders while a balance is still outstanding.','remaining balance, balance, settle, due, deadline, when to pay, outstanding',3,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(20,3,'What if I have an unpaid balance?','Tenants with an outstanding balance cannot use tenant services (maintenance, room change, stay extension) until the balance is settled. Please settle it as soon as possible to avoid issues with your stay.','unpaid, outstanding, overdue, late payment, not paid, locked',4,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(21,3,'How do I view my billing and receipts?','Log in to your tenant account and open your Dashboard or History to see your invoices, payments, and remaining balance.','receipt, invoice, billing, history, statement, proof, view bill',5,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(22,4,'What are the quiet hours?','Quiet hours are observed from 10:00 PM to 7:00 AM.','quiet hours, quiet, noise, noisy, loud, ingay, sleep',1,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(23,4,'What are the visiting hours?','Visitors are allowed from 8:00 AM to 9:00 PM and must register at the front desk and present a valid ID.','visiting hours, visitor, visit, guest, bisita, friends visit',2,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(24,4,'Are overnight visitors allowed?','No. Overnight stays by non-boarders are not permitted.','overnight visitor, overnight, sleep over, sleepover, stay the night, non-boarder',3,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(25,4,'Is smoking or vaping allowed?','No. Smoking and vaping are prohibited inside the boarding house. Violations are subject to a ₱500 penalty.','smoking, smoke, vape, vaping, cigarette, yosi, penalty',4,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(26,4,'Are pets allowed?','Please contact the administrator to ask about pets before booking, as this depends on the room and house policies.','pets, pet, dog, cat, animal, aso, pusa',5,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(27,4,'Is there parking available?','Please contact the administrator to ask about parking availability before your move-in.','parking, park, car, motorcycle, motor, vehicle',6,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(28,5,'How can I request room maintenance?','Log in to your tenant account, go to Services, select Maintenance Request, and provide the details of your concern.','maintenance, repair, broken, sira, fix, not working, leak, aircon problem',1,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(29,5,'How can I request a room change?','Go to Services, select Room Change Request, choose an available room, and submit your reason and required payment proof.','room change request, request a room change, change room, transfer room, lipat',2,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(30,5,'How can I extend my stay?','Go to Services, select Stay Extension, provide your preferred extension date, reason, and payment details, then submit your request.','extend, extension, extend my stay, stay longer, longer stay',3,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(31,5,'How can I check my request status?','Visit the Services section of your tenant account to check the status of your submitted requests.','request status, my request, track request, service status',4,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27'),(32,6,'Where are you located?','We are located at 1517 M.H. Del Pilar St., Ermita, Manila.','location, located, address, where, saan, directions, map',1,1,1,'2026-11-17 19:13:41','2026-11-17 19:22:23'),(33,6,'How can I contact the administrator?','You can reach us at +63 912 345 6789 or email info@jlmcozycabin.com. Our office hours are Mon–Sun, 8:00 AM – 8:00 PM.','contact, phone, number, email, call, text, admin, administrator, talk to someone, human',2,1,1,'2026-11-17 19:13:41','2026-11-17 19:22:05'),(34,6,'What are your office hours?','Our office is open Mon–Sun, 8:00 AM – 8:00 PM.','office hours, open, opening, business hours, schedule',3,1,0,'2026-11-17 19:13:41','2026-11-17 19:17:27');
