INSERT INTO `chatbot_settings` VALUES (1,'bot_name','JLM Cozy Cabin Assistant','2026-11-17 19:13:41','2026-11-17 19:13:41'),(2,'bot_subtitle','How can we help you?','2026-11-17 19:13:41','2026-11-17 19:13:41'),(3,'welcome_message','Hello! Welcome to JLM Cozy Cabin!\nI\'m here to assist you with your inquiries. Please select a category below.','2026-11-17 19:13:41','2026-11-17 19:13:41'),(4,'greeting_reply','Hello there! 👋 Ask me anything about our rooms, reservations, payments, or house rules — or pick a category below.','2026-11-17 19:13:41','2026-11-17 19:13:41'),(5,'fallback_message','Sorry, I couldn\'t find an answer to your question. Please contact the administrator for further assistance.','2026-11-17 19:13:41','2026-11-17 19:13:41'),(6,'back_message','Would you like to explore another category?','2026-11-17 19:13:41','2026-11-17 19:13:41'),(7,'closing_message','Thank you for using the JLM Cozy Cabin Assistant! Have a great day!','2026-11-17 19:13:41','2026-11-17 19:13:41'),(8,'contact_phone','+63 912 345 6789','2026-11-17 19:13:41','2026-11-17 19:13:41'),(9,'contact_email','info@jlmcozycabin.com','2026-11-17 19:13:41','2026-11-17 19:13:41');
